(ns clojure2d.color.blend-test
  "Per-channel blend modes checked against the oracle generated by `utils/blend/gen_reference.py`:
  source formulas (W3C Compositing Level 1, pegtop.net, Photoshop) in numpy, the modulus family's
  unwrapped formulas, bitwise modes and Pillow `ImageChops`."
  (:require [clojure.test :refer [deftest is testing]]
            [clojure.edn :as edn]
            [clojure.java.io :as io]
            [fastmath.core :as m]
            [clojure2d.color :as c]
            [clojure2d.color.blend :as b]
            [fastmath.vector :as v]
            [clojure2d.test-predicates :refer [rel-close? throws-data?]]))

(def reference (delay (-> "blend/blend_reference.edn" io/resource slurp edn/read-string)))

(defn- pairs [k] (partition 2 (k @reference)))
(def ^:private points (delay (concat (pairs :grid) (pairs :random))))

(defn- mode [k] @(ns-resolve 'clojure2d.color.blend (symbol (name k))))

;; G1: existing per-channel modes

(deftest coverage-test
  ;; every registered mode is checked against the oracle; nor, nand, xnor registered (B4)
  (let [{:keys [formula modulus bitwise]} @reference]
    (is (= (set (keys b/blends)) (set (concat (keys formula) (keys modulus) (keys bitwise)))))
    (is (every? (set (keys b/blends)) [:nor :nand :xnor]))))

(deftest formula-modes-test
  ;; W3C, Photoshop and pegtop formulas on the grid and random pairs: 1e-12 relative to max(1, |expected|)
  (doseq [[k expected] (:formula @reference)
          :let [f (mode k)]
          [[x y] e] (map vector @points expected)]
    (is (rel-close? 1.0e-12 e (f x y)) (str k " " x " " y))))

(defn- wrapped-close?
  "Is `v` the author's wrap (mod 256, capped at 255) of the unwrapped oracle value `u`? The unwrapped
  values reach 1e18 at guarded divisions, so the tolerance is 1e-12 relative to max(1, |u|); within it
  of a multiple of 256 both 0 and the cap 255 are accepted."
  [^double u ^double v]
  (let [tol (m/* 1.0e-12 (m/max 1.0 (m/abs u)))
        r (m/mod u 256.0)]
    (or (m/<= (m/abs (m/- v (m/min r 255.0))) tol)
        (and (or (m/<= r tol) (m/>= r (m/- 256.0 tol)))
             (or (m/<= v tol) (== v 255.0))))))

(deftest modulus-modes-test
  ;; author's unwrapped formula, wrapped with mod 256 and capped at 255 (B6); results in [0, 255]
  (doseq [[k unwrapped] (:modulus @reference)
          :let [f (mode k)]
          [[x y] u] (map vector @points unwrapped)
          :let [v (f x y)]]
    (is (m/<= 0.0 v 255.0) (str k " " x " " y))
    (is (wrapped-close? u v) (str k " " x " " y))))

(deftest modulus-cap-test
  (testing "B6: results in (255, 256) are capped, integer-valued results equal plain mod 256"
    (is (== 255.0 (b/madd 200.0 55.5) (b/msubtract 0.0 1.0e-14)))
    (is (== 0.0 (b/madd 200.0 56.0)))
    (is (== 44.0 (b/madd 200.0 100.0)))))

(deftest G2-fixes-test
  (let [grid (range 0.0 256.0)]
    (testing "B1: soft burn continuous at a + b = 255 (value 127.5)"
      (doseq [a (butlast grid) :let [b (- 255.0 a)]] ; a = 255, b = 0 is the 0/0 corner (value 0)
        (is (m/<= (m/abs (m/- 127.5 (b/softburn a b))) 1.0e-12) (str a))
        (is (m/<= (m/abs (m/- (b/softburn a b) (b/softburn a (+ b 1.0e-9)))) 1.0e-6) (str a))))
    (testing "B2: linear light = stamp"
      (doseq [a grid bl grid]
        (is (== (b/stamp a bl) (b/linearlight a bl)))
        (is (== (b/mstamp a bl) (b/mlinearlight a bl)))))
    (testing "B3: pin light keeps the base inside [2b - 255, 2b]"
      (is (== 100.0 (b/pinlight 200.0 50.0)))
      (is (== 145.0 (b/pinlight 100.0 200.0)))
      (is (== 120.0 (b/pinlight 120.0 127.5))))))

(deftest bitwise-modes-test
  ;; low 8 bits of the truncated channel values, exact
  (doseq [[k expected] (:bitwise @reference)
          :let [f (mode k)]
          [[x y] e] (map vector @points expected)]
    (is (== e (f x y)) (str k " " x " " y))))

(def ^:private pillow-exact #{:add :subtract :madd :msubtract :darken :lighten :difference})

(deftest pillow-test
  ;; Pillow ImageChops on integer inputs: exact for the listed modes, else within 1 (integer rounding);
  ;; Pillow soft_light is the pegtop soft light, within 2.3 (Pillow's integer approximation)
  (let [pts (partition 2 (:pillow-points @reference))]
    (doseq [[k expected] (:pillow @reference)
            :let [f (mode k)
                  tol (cond (pillow-exact k) 0.0 (= k :pegtoplight) 2.3 :else 1.0)]
            [[x y] e] (map vector pts expected)]
      (is (m/<= (m/abs (m/- (double e) (f x y))) tol) (str k " " x " " y)))))

(deftest singular-points-test
  (testing "0/0 takes the zero-numerator value, x/0 saturates"
    (is (== 0.0 (b/dodge 0.0 255.0) (b/reflect 0.0 255.0) (b/divide 0.0 0.0) (b/burn 200.0 0.0)))
    (is (== 255.0 (b/dodge 1.0 255.0) (b/burn 255.0 0.0) (b/freeze 255.0 0.0) (b/divide 1.0 0.0)))))

(deftest namespace-docstring-test
  (let [doc (:doc (meta (find-ns 'clojure2d.color.blend)))]
    (is (re-find #"backdrop" doc))
    (is (re-find #"mod 256" doc))))

;; G3: combinators and colorspace blends

(defn- vec-close? [tol expected actual]
  (every? true? (map (partial rel-close? tol) expected actual)))

(deftest alpha-blending-test
  ;; W3C source-over with blending, unpremultiplied, semi-transparent and transparent inputs:
  ;; 1e-9 relative to max(1, |expected|)
  (let [{:keys [cb cs] :as comp} (:compositing @reference)]
    (doseq [k [:multiply :screen]
            [x y e] (map vector cb cs (comp k))]
      (is (vec-close? 1.0e-9 e (b/blend-colors (mode k) (c/color x) (c/color y))) (str k " " x " " y)))))

(deftest blend-colors-test
  (testing "opaque colors: blended channels, alpha 255; a mode per channel"
    (is (= (v/vec4 (b/multiply 200.0 100.0) (b/screen 50.0 60.0) (b/darken 10.0 20.0) 255.0)
           (b/blend-colors b/multiply b/screen b/darken (c/color 200 50 10) (c/color 100 60 20)))))
  (testing "transparent source keeps the backdrop, transparent backdrop gives the source"
    (is (vec-close? 1.0e-12 [200 50 10 255] (b/blend-colors b/multiply (c/color 200 50 10) (c/color 100 60 20 0))))
    (is (vec-close? 1.0e-12 [100 60 20 255] (b/blend-colors b/multiply (c/color 200 50 10 0) (c/color 100 60 20))))))

(deftest transparent-pair-test
  ;; B5: no NaN on an alpha grid including 0; both alphas 0 give the blended channels with alpha 0
  (let [alphas [0.0 1.0e-12 1.0 128.0 255.0]]
    (doseq [ab alphas as alphas
            f [b/multiply b/screen b/overlay]
            :let [r (b/blend-colors f (c/color 200 50 10 ab) (c/color 100 60 20 as))]]
      (is (not-any? m/nan? r) (str ab " " as))
      (is (m/<= 0.0 (r 3) 255.0))))
  (is (= (v/vec4 (b/multiply 200.0 100.0) (b/multiply 50.0 60.0) (b/multiply 10.0 20.0) 0.0)
         (b/blend-colors b/multiply (c/color 200 50 10 0) (c/color 100 60 20 0))))
  (is (not-any? m/nan? (b/hue (c/color 200 50 10 0) (c/color 20 120 220 0))))
  (is (zero? ((b/ch0 (c/color 200 50 10 0) (c/color 20 120 220 0)) 3))))

(deftest blend-palettes-test
  (let [p1 [:red :green :blue]
        p2 [:white :gray]]
    (is (= (mapv (partial b/blend-colors b/multiply) (c/palette p1) (c/palette p2))
           (b/blend-palettes b/multiply p1 p2)))
    (is (= 2 (count (b/blend-palettes b/multiply p1 p2))))
    (is (= (mapv (partial b/blend-colors b/add b/darken b/screen) (c/palette p1) (c/palette p2))
           (b/blend-palettes b/add b/darken b/screen p1 p2)))))

(deftest blend-gradients-test
  (let [g1 (c/gradient [:black :white])
        g2 (c/gradient [:red :blue])
        g (b/blend-gradients b/screen g1 g2)
        g3 (b/blend-gradients b/add b/darken b/screen g1 g2)]
    (doseq [t [0.0 0.25 0.5 1.0]]
      (is (= (b/blend-colors b/screen (g1 t) (g2 t)) (g t)))
      (is (= (b/blend-colors b/add b/darken b/screen (g1 t) (g2 t)) (g3 t))))))

(def ^:private hsb-pairs
  ;; saturated, not dark colors: the HSB round trip keeps all three channels
  [[[200 50 30] [20 120 220]] [[90 200 120] [240 200 40]] [[60 40 180] [250 120 200]]])

(deftest hsb-blends-test
  ;; HSB channel(s) of the result come from the right color: 1e-9 relative
  (doseq [[x y] hsb-pairs
          :let [hb (c/to-HSB (c/color x)) hs (c/to-HSB (c/color y))]]
    (is (vec-close? 1.0e-9 [(hs 0) (hb 1) (hb 2)] (c/to-HSB (b/hue x y))) (str x y))
    (is (vec-close? 1.0e-9 [(hb 0) (hs 1) (hb 2)] (c/to-HSB (b/saturation x y))) (str x y))
    (is (vec-close? 1.0e-9 [(hb 0) (hb 1) (hs 2)] (c/to-HSB (b/luminosity x y))) (str x y))
    (is (vec-close? 1.0e-9 [(hs 0) (hs 1) (hb 2)] (c/to-HSB (b/color x y))) (str x y))
    (is (== 255.0 ((b/hue x y) 3)))))

(deftest channel-blends-test
  (let [x (c/color 200 50 30) y (c/color 20 120 220)]
    (is (vec-close? 1.0e-12 [20 50 30 255] (b/ch0 x y)))
    (is (vec-close? 1.0e-12 [200 120 30 255] (b/ch1 x y)))
    (is (vec-close? 1.0e-12 [200 50 220 255] (b/ch2 :RGB x y)))
    (is (vec-close? 1.0e-9 (c/to-HSB (b/hue x y)) (c/to-HSB (b/ch0 :HSB x y))))))

(deftest luminosity-rename-test
  (is (nil? (ns-resolve 'clojure2d.color.blend 'luminocity)))
  (is (fn? b/luminosity)))

;; G4: gaps

(deftest nonseparable-modes-test
  ;; W3C hue, saturation, color, luminosity (Lum, ClipColor, SetLum, Sat, SetSat) and darker / lighter
  ;; color vs the numpy oracle, composited with alpha: 1e-9 relative to max(1, |expected|)
  (let [{:keys [cb cs] :as ns} (:nonseparable @reference)]
    (doseq [k [:w3c-hue :w3c-saturation :w3c-color :w3c-luminosity :darker-color :lighter-color]
            [x y e] (map vector cb cs (ns k))]
      (is (vec-close? 1.0e-9 e ((mode k) (c/color x) (c/color y))) (str k " " x " " y)))))

(deftest nonseparable-properties-test
  (let [x (c/color 200 50 30) y (c/color 20 120 220)
        lum (fn [c] (+ (* 0.3 (c 0)) (* 0.59 (c 1)) (* 0.11 (c 2))))]
    (testing "luminance comes from the right color"
      (is (m/<= (m/abs (m/- (lum x) (lum (b/w3c-hue x y)))) 1.0e-9))
      (is (m/<= (m/abs (m/- (lum x) (lum (b/w3c-color x y)))) 1.0e-9))
      (is (m/<= (m/abs (m/- (lum y) (lum (b/w3c-luminosity x y)))) 1.0e-9)))
    (testing "channels stay in [0, 255]"
      (doseq [f [b/w3c-hue b/w3c-saturation b/w3c-color b/w3c-luminosity]
              [p q] [[[255 255 0] [0 0 255]] [[0 0 10] [255 250 0]] [[128 128 128] [255 0 0]]]
              :let [r (f p q)]]
        (is (every? #(m/<= -1.0e-9 % 255.000000001) (take 3 r)) (str p q))))
    (testing "gray source has no saturation: w3c-saturation gives a gray of the backdrop luminance"
      (let [r (b/w3c-saturation x (c/color 100 100 100))]
        (is (vec-close? 1.0e-9 (repeat 3 (lum x)) (take 3 r)))))))

(deftest darker-lighter-color-test
  ;; (0 10 10) and (5 0 50) have the same Lum (7.0): ties keep the backdrop
  (let [p (c/color 0 10 10) q (c/color 5 0 50)]
    (is (= p (b/darker-color p q)) "tie")
    (is (= q (b/darker-color q p)) "tie")
    (is (= p (b/lighter-color p q)) "tie")
    (is (= (c/color 10 20 30) (b/darker-color (c/color 200 200 200) (c/color 10 20 30))))
    (is (= (c/color 200 200 200) (b/lighter-color (c/color 200 200 200) (c/color 10 20 30))))))

(deftest blend-fn-test
  (is (identical? b/multiply (b/blend-fn :multiply)))
  (is (identical? b/screen (b/blend-fn b/screen)))
  (let [f (fn [a _] a)] (is (identical? f (b/blend-fn f))))
  (is (throws-data? {:blend :nope} #(b/blend-fn :nope)))
  (is (throws-data? {:blend nil} #(b/blend-fn nil)))
  (is (throws-data? {:blend "multiply"} #(b/blend-fn "multiply"))))

(deftest opacity-test
  (doseq [[x y] (take 200 @points)]
    (is (== x ((b/opacity :multiply 0.0) x y)))
    (is (== (b/multiply x y) ((b/opacity b/multiply 1.0) x y)))
    (is (rel-close? 1.0e-12 (+ x (* 0.3 (- (b/screen x y) x))) ((b/opacity :screen 0.3) x y))))
  (is (throws-data? {:blend :nope} #(b/opacity :nope 0.5))))

;; Review fixes

(deftest keyword-modes-test
  ;; blend-colors, blend-palettes, blend-gradients resolve keywords with blend-fn (a keyword used to act as normal)
  (let [x (c/color 200 50 10) y (c/color 100 60 20)
        g1 (c/gradient [:black :white]) g2 (c/gradient [:red :blue])]
    (is (= (b/blend-colors b/multiply x y) (b/blend-colors :multiply x y)))
    (is (= (b/blend-colors b/add b/darken b/screen x y) (b/blend-colors :add :darken :screen x y)))
    (is (= (b/blend-palettes b/multiply [x] [y]) (b/blend-palettes :multiply [x] [y])))
    (is (= ((b/blend-gradients b/screen g1 g2) 0.3) ((b/blend-gradients :screen g1 g2) 0.3)))
    (is (throws-data? {:blend :nope} #(b/blend-colors :nope x y)))
    (is (throws-data? {:blend :nope} #(b/blend-gradients :nope g1 g2)))))

(deftest color-blends-test
  (is (= #{:hue :saturation :luminosity :color :w3c-hue :w3c-saturation :w3c-color :w3c-luminosity
           :darker-color :lighter-color :ch0 :ch1 :ch2}
         (set (keys b/color-blends))))
  (is (empty? (filter (set (keys b/blends)) (keys b/color-blends)))))

(deftest unknown-colorspace-test
  (is (throws-data? {:colorspace :nope} #(b/ch0 :nope (c/color 1 2 3) (c/color 4 5 6)))))
